def find_kth(arr1, arr2, k):
    """
    Finds the k-th element from the two sorted arrays.

    :param arr1: List[int], first sorted array
    :param arr2: List[int], second sorted array
    :param k: int, the position (1-based) of the element to find
    :return: int, the k-th element in the merged sorted array
    """
    def kth_helper(a, b, k):
        # Base cases
        if not a:
            return b[k - 1]
        if not b:
            return a[k - 1]
        if k == 1:
            return min(a[0], b[0])

        # Divide and conquer: Compare middle elements
        mid_a = min(len(a), k // 2)
        mid_b = k - mid_a
        if mid_b > len(b):
            mid_b = len(b)
            mid_a = k - mid_b

        if a[mid_a - 1] < b[mid_b - 1]:
            return kth_helper(a[mid_a:], b, k - mid_a)
        else:
            return kth_helper(a, b[mid_b:], k - mid_b)

    return kth_helper(arr1, arr2, k)

# Example test
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
```

