def merge_dictionaries_three(dict1, dict2, dict3):
    # Combine all three dictionaries into one
    merged_dict = {}
    for d in (dict1, dict2, dict3):
        for key, value in d.items():
            # Only add key-value pairs if the key is not already in the merged dictionary
            if key not in merged_dict:
                merged_dict[key] = value
    return merged_dict

# Example usage and test cases
assert merge_dictionaries_three(
    {"R": "Red", "B": "Black", "P": "Pink"},
    {"G": "Green", "W": "White"},
    {"O": "Orange", "W": "White", "B": "Black"}
) == {'B': 'Black', 'R': 'Red', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'O': 'Orange'}

assert merge_dictionaries_three(
    {"R": "Red", "B": "Black", "P": "Pink"},
    {"G": "Green", "W": "White"},
    {"L": "Lavender", "B": "Blue"}
) == {'R': 'Red', 'B': 'Black', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'L': 'Lavender'}
